mapper.select:
SELECT s.id, s.activity_id, a.title AS activity_title, a.start_time AS activity_start_time, a.duration AS activity_duration, s.student_id, u.real_name AS student_name, si.student_no, si.college, s.status, s.signup_time, s.reason, s.audit_remark FROM activity_signup s JOIN volunteer_activity a ON a.id = s.activity_id JOIN student_info si ON si.id = s.student_id LEFT JOIN sys_user u ON u.id = si.user_id WHERE s.deleted = 0 AND a.deleted = 0
AND s.student_id = #{scopeStudentId}
AND a.org_id = #{scopeOrgId}
AND (u.real_name ILIKE CONCAT('%', #{q.keyword}::text, '%') OR si.student_no ILIKE CONCAT('%', #{q.keyword}::text, '%') OR a.title ILIKE CONCAT('%', #{q.keyword}::text, '%'))
AND s.status = #{q.status}
AND s.activity_id = #{q.activityId}
AND s.student_id = #{q.studentId}
AND si.college = #{q.college}
ORDER BY s.id DESC
